from rich.console import Console
from rich.traceback import Traceback
import io

def test_notes():
    console = Console(file=io.StringIO(), force_terminal=False)

    class MyException(Exception):
        pass

    try:
        try:
            raise MyException("Something went wrong")
        except MyException as e:
            e.add_note("This is a note for the exception")
            raise
    except MyException:
        tb = Traceback()
        console.print(tb)

    output = console.file.getvalue()
    assert "This is a note for the exception" in output, f"Notes not found in output: {output}"

if __name__ == "__main__":
    test_notes()
# CLAIM 1: Exception.__notes__ should be printed in Traceback
EOF

